rm -rf /tmp/mut && mkdir /tmp/mut && cd /travail && cp -r Atm Atm.Contract Atm.Tests Atm.slnx /tmp/mut/ && rm -rf /tmp/mut/*/bin /tmp/mut/*/obj
cd /tmp/mut && cp Atm/CashMachine.cs /tmp/orig.cs
run() { # $1 = name, python replacement already applied
  old=$(dotnet test --filter "FullyQualifiedName~CashMachineTests" 2>&1 | grep -oE "Failed: +[0-9]+" | head -1)
  new=$(dotnet test --filter "FullyQualifiedName~Renforts" 2>&1 | grep -oE "Failed: +[0-9]+" | head -1)
  echo "$1 => anciens: $old | renforts: $new"; cp /tmp/orig.cs Atm/CashMachine.cs; }
mut() { python3 -c "
import sys;p='Atm/CashMachine.cs';s=open(p).read();a,b=sys.argv[1],sys.argv[2];assert a in s,a;open(p,'w').write(s.replace(a,b,1))" "$1" "$2"; }

mut "return Refuse(AtmStatus.CannotDispense, account);" "dispenser.Dispense(new NoteCounts(9,9,9)); return Refuse(AtmStatus.CannotDispense, account);"; run "M1 appel module sur CannotDispense"
mut "dispensed += pass;" "dispensed = pass;"; run "M2 notes sorties = dernier passage"
mut "var stock = dispenser.Stock;" "var stock = initialStock;"; mut "public const int DailyLimit = 200;" "public const int DailyLimit = 200; private readonly NoteCounts initialStock = dispenser.Stock;"; run "M3 stock mémorisé à la construction"
mut "return Refuse(AtmStatus.InvalidAmount, account);
        }

        if (dispenser.Jammed" "return Refuse(AtmStatus.InvalidAmount, account);
        }
        dispenser.Load(new NoteCounts(0,0,0));
        if (dispenser.Jammed"; run "M4 Load vide avant contrôles dépôt"

